1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_RATE = 0.1;
3	const DEDUCTIBLE = 100;
4	const CAP_MULTIPLIER = 2;
5	
6	interface CatalogEntry {
7	  basePremium: number;
8	  insuranceValue: number;
9	}
10	
11	const CATALOG: Record<string, CatalogEntry> = {
12	  sword: { basePremium: 100, insuranceValue: 1000 },
13	  amulet: { basePremium: 60, insuranceValue: 600 },
14	  staff: { basePremium: 80, insuranceValue: 800 },
15	  potion: { basePremium: 40, insuranceValue: 400 },
16	  rune: { basePremium: 25, insuranceValue: 250 },
17	  moonstone: { basePremium: 25, insuranceValue: 250 },
18	};
19	
20	const basePremiumOf = (type: string): number => CATALOG[type]?.basePremium ?? 0;
21	const insuranceValueOf = (type: string): number => CATALOG[type]?.insuranceValue ?? 0;
22	
23	const sumBy = <T>(items: readonly T[], value: (item: T) => number): number =>
24	  items.reduce((total, item) => total + value(item), 0);
25	
26	interface ConditionalRate<T> {
27	  applies: (subject: T) => boolean;
28	  rate: number;
29	}
30	
31	const sumApplicableRates = <T>(rates: readonly ConditionalRate<T>[], subject: T): number =>
32	  sumBy(rates, ({ applies, rate }) => (applies(subject) ? rate : 0));
33	
34	interface Item {
35	  type: string;
36	  material?: string;
37	  enchantment?: number;
38	  cursed?: boolean;
39	}
40	
41	const HIGH_ENCHANTMENT_PREMIUM_THRESHOLD = 5;
42	
43	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
44	
45	const isCursed = (item: Item): boolean => item.cursed === true;
46	const hasHighEnchantmentForPremium = (item: Item): boolean =>
47	  enchantmentOf(item) >= HIGH_ENCHANTMENT_PREMIUM_THRESHOLD;
48	
49	const SURCHARGE_RATES: ReadonlyArray<ConditionalRate<Item>> = [
50	  { applies: isCursed, rate: 0.5 },
51	  { applies: hasHighEnchantmentForPremium, rate: 0.3 },
52	];
53	
54	const itemSurcharge = (item: Item): number =>
55	  basePremiumOf(item.type) * sumApplicableRates(SURCHARGE_RATES, item);
56	
57	const itemsSurcharge = (items: Item[]): number => sumBy(items, itemSurcharge);
58	
59	interface QuoteStep {
60	  op: "quote";
61	  items: Item[];
62	}
63	
64	interface Damage {
65	  itemType: string;
66	  amount: number;
67	}
68	
69	interface ClaimStep {
70	  op: "claim";
71	  policy: number;
72	  incident: {
73	    cause: string;
74	    damages: Damage[];
75	  };
76	}
77	
78	type Step = QuoteStep | ClaimStep;
79	
80	interface Customer {
81	  yearsWithMHPCO: number;
82	}
83	
84	interface Scenario {
85	  customer: Customer;
86	  steps: Step[];
87	}
88	
89	interface QuoteResult {
90	  premium: number;
91	}
92	
93	interface ClaimResult {
94	  payout: number;
95	  remainingCap: number;
96	}
97	
98	type StepResult = QuoteResult | ClaimResult;
99	
100	interface ScenarioResult {
101	  results: StepResult[];
102	}
103	
104	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
105	const COMPONENT_BLOCK_SIZE = 3;
106	const COMPONENT_BLOCK_BASE = 60;
107	
108	const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
109	const roundDownInMHPCOsFavor = (amount: number): number => Math.floor(amount);
110	
111	const countItemsByType = (items: Item[]): Array<[string, number]> => {
112	  const counts = new Map<string, number>();
113	  for (const item of items) {
114	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
115	  }
116	  return [...counts];
117	};
118	
119	const isComponentBlock = (type: string, count: number): boolean =>
120	  COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE;
121	
122	const basePremiumForSameTypeItems = (type: string, count: number): number =>
123	  isComponentBlock(type, count) ? COMPONENT_BLOCK_BASE : basePremiumOf(type) * count;
124	
125	const itemsBasePremium = (items: Item[]): number =>
126	  sumBy(countItemsByType(items), ([type, count]) => basePremiumForSameTypeItems(type, count));
127	
128	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
129	
130	const LOYALTY_YEARS_THRESHOLD = 2;
131	const LOYALTY_DISCOUNT_RATE = 0.2;
132	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
133	
134	interface QuoteContext {
135	  customer: Customer;
136	  isFollowUp: boolean;
137	}
138	
139	const isLoyalCustomer = ({ customer }: QuoteContext): boolean =>
140	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
141	
142	const isFollowUpQuote = ({ isFollowUp }: QuoteContext): boolean => isFollowUp;
143	
144	const DISCOUNT_RATES: ReadonlyArray<ConditionalRate<QuoteContext>> = [
145	  { applies: isLoyalCustomer, rate: LOYALTY_DISCOUNT_RATE },
146	  { applies: isFollowUpQuote, rate: FOLLOW_UP_DISCOUNT_RATE },
147	];
148	
149	const totalDiscount = (base: number, context: QuoteContext): number =>
150	  base * sumApplicableRates(DISCOUNT_RATES, context);
151	
152	const quotePremium = ({ items }: QuoteStep, context: QuoteContext): number => {
153	  const base = itemsBasePremium(items);
154	  const premiumBeforeFee =
155	    base + itemsSurcharge(items) + firstInsuranceSurcharge(base) - totalDiscount(base, context);
156	  return roundUpInMHPCOsFavor(premiumBeforeFee + PROCESSING_FEE);
157	};
158	
159	interface Policy {
160	  items: Item[];
161	  remainingCap: number;
162	}
163	
164	const createPolicy = (step: QuoteStep): Policy => ({
165	  items: step.items,
166	  remainingCap: sumBy(step.items, (item) => insuranceValueOf(item.type)) * CAP_MULTIPLIER,
167	});
168	
169	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
170	const FULL_REIMBURSEMENT_RATE = 1;
171	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
172	
173	const hasHighEnchantmentForClaim = (item: Item): boolean =>
174	  enchantmentOf(item) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
175	
176	const reimbursementRate = (item: Item): number =>
177	  hasHighEnchantmentForClaim(item) ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
178	
179	const damagePayout = (damage: Damage, item: Item): number =>
180	  Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE);
181	
182	const findItemByType = (policy: Policy, itemType: string): Item => {
183	  const item = policy.items.find((candidate) => candidate.type === itemType);
184	  if (item === undefined) throw new Error(`Claim references item not in policy: ${itemType}`);
185	  return item;
186	};
187	
188	const payoutForDamage = (damage: Damage, policy: Policy): number =>
189	  damagePayout(damage, findItemByType(policy, damage.itemType));
190	
191	const calculatePayout = (damages: Damage[], policy: Policy): number => {
192	  const rawPayout = sumBy(damages, (damage) => payoutForDamage(damage, policy));
193	  return roundDownInMHPCOsFavor(Math.min(rawPayout, policy.remainingCap));
194	};
195	
196	const assertNonNegativeDamage = (damage: Damage): void => {
197	  if (damage.amount < 0) throw new Error(`Negative damage amount: ${damage.amount}`);
198	};
199	
200	const assertDamageCountsWithinPolicy = (damages: Damage[], policy: Policy): void => {
201	  const insuredCounts = new Map<string, number>();
202	  for (const item of policy.items) {
203	    insuredCounts.set(item.type, (insuredCounts.get(item.type) ?? 0) + 1);
204	  }
205	  const damageCounts = new Map<string, number>();
206	  for (const damage of damages) {
207	    damageCounts.set(damage.itemType, (damageCounts.get(damage.itemType) ?? 0) + 1);
208	  }
209	  for (const [type, count] of damageCounts) {
210	    if (count > (insuredCounts.get(type) ?? 0)) {
211	      throw new Error(`More damages of type ${type} than items insured`);
212	    }
213	  }
214	};
215	
216	const processClaim = (step: ClaimStep, policies: Map<number, Policy>): ClaimResult => {
217	  step.incident.damages.forEach(assertNonNegativeDamage);
218	  const policy = policies.get(step.policy)!;
219	  assertDamageCountsWithinPolicy(step.incident.damages, policy);
220	  const payout = calculatePayout(step.incident.damages, policy);
221	  policy.remainingCap -= payout;
222	  return { payout, remainingCap: policy.remainingCap };
223	};
224	
225	const assertKnownItemType = (item: Item): void => {
226	  if (!(item.type in CATALOG)) throw new Error(`Unknown item type: ${item.type}`);
227	};
228	
229	const processQuote = (
230	  step: QuoteStep,
231	  customer: Customer,
232	  policies: Map<number, Policy>,
233	): QuoteResult => {
234	  step.items.forEach(assertKnownItemType);
235	  const context: QuoteContext = { customer, isFollowUp: policies.size > 0 };
236	  policies.set(policies.size, createPolicy(step));
237	  return { premium: quotePremium(step, context) };
238	};
239	
240	const processStep = (
241	  step: Step,
242	  customer: Customer,
243	  policies: Map<number, Policy>,
244	): StepResult =>
245	  step.op === "quote"
246	    ? processQuote(step, customer, policies)
247	    : processClaim(step, policies);
248	
249	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
250	  const policies = new Map<number, Policy>();
251	  const results = steps.map((step) => processStep(step, customer, policies));
252	  return { results };
253	};
